WITH sales_agg AS ( SELECT c.c_customer_id AS customer_id, i.i_category AS category, SUM(cs.cs_net_paid) AS total_net_paid, SUM(cs.cs_net_profit) AS total_net_profit, COUNT(*) AS order_count, CASE WHEN SUM(cs.cs_net_profit) > 0 THEN 'PROFIT' ELSE 'LOSS' END AS profit_flag FROM catalog_sales cs JOIN customer c ON cs.cs_bill_customer_sk = c.c_customer_sk JOIN item i ON cs.cs_item_sk = i.i_item_sk JOIN promotion p ON cs.cs_promo_sk = p.p_promo_sk GROUP BY c.c_customer_id, i.i_category ) SELECT customer_id, category, total_net_paid, total_net_profit, order_count, profit_flag, RANK() OVER (PARTITION BY category ORDER BY total_net_paid DESC) AS revenue_rank, DENSE_RANK() OVER (PARTITION BY category ORDER BY total_net_profit DESC) AS profit_rank FROM sales_agg WHERE order_count > 5 ORDER BY category, revenue_rank
